'use strict';
// Verify delivery, scope and example isolation. This does not grade a live AI's prose.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {environment,examples}=require('./native-fixtures-20261003.cjs');
const {ctx:c,load}=environment();['prompt-brief','prompt-packet'].forEach(load);
const fixture=examples(c),Q=c.JY_READING_QUALITY,W=c.JYReadingWorkflow,P=c.JYPromptPacket;
const q='今年會發生非現任的肉體關係嗎？',results=[];
assert.equal(Q.readingVersion,'15.0.0');assert.equal(W.version,'2.4.0');
for(const [method,chart]of Object.entries(fixture.charts)){
 const before=JSON.stringify(chart),text=P.build(method,chart,q),record=P.get(text);
 const illustrative=[...text.matchAll(/【原創成稿示範｜只學鋪陳，不是本次資料】([^\n]+)/g)].map(m=>JSON.parse(m[1]));
 assert(illustrative.length,method+' real exporter includes an isolated composition example');
 assert(illustrative.every(e=>e.schema==='jy.voice-example/1'&&e.status==='illustrative_only'&&e.method===method),method+' only the active method example is included');
 assert(text.includes('【整體解說，不按資料順序朗讀】'),method+' combines positions instead of reciting a position ledger');
 assert(text.includes('【主判必須收斂】'),method+' requires resolving competing interpretations');
 assert(text.includes('【目前走向與條件推演分開】'),method+' distinguishes the current outlook from advice scenarios');
 assert(text.includes('排除現任只限定問事對象，不證明另一人存在'),method+' exclusion does not invent a partner');
 assert(text.includes('未列職業、輪班、同事、特定對象'),method+' unseen background remains unknown');
 assert(text.includes('明示「肉體關係／性關係」的成立題要回答性關係是否發生'),method+' original event is not reduced to general attraction');
 assert(text.includes('示例的牌曜、人物、情境、時間與結論全部禁止移入本題'),method+' fictional examples are explicitly barred from case facts');
 assert(text.endsWith(W.footer),method+' intentional final shop close retained');
 assert(record&&record.readingData,method+' original structured reading retained');
 assert.equal(JSON.stringify(chart),before,method+' original chart and card order untouched');
 results.push({method,status:'passed',isolatedExamples:illustrative.length,characters:text.length,chartUnchanged:true});
}
assert.equal(results.length,15);
const ids=[76,48,71,22,77],up=[false,true,false,true,true];
const positions=['目前事件狀態','促成事件成立的力量','阻礙事件成立的力量','可介入的方向','截至2026年的事件成立傾向'];
const five={method:'five_card',sourceProfile:'rws_reversals',cards:ids.map((id,i)=>({...fixture.cards.find(card=>card.id===id),isUp:up[i],position:positions[i],binding:{eventId:'QUERY_EVENT'}}))};
const fiveBefore=JSON.stringify(five),fiveText=P.build('tarot',five,q),native=c.JYNativeCards.tarot(five);
assert.deepEqual(Array.from(native.records,r=>r.id),ids);assert.deepEqual(Array.from(native.records,r=>r.position),positions);
assert.deepEqual(Array.from(native.records,r=>r.direction),['逆位','正位','逆位','正位','正位']);
assert(fiveText.includes('權杖王牌在建議位不證明性關係會發生'));
assert(fiveText.includes('未出現惡魔、戀人等特定牌也不能當作不發生的證據'));
const facts=fiveText.split('【全部實際塔羅牌】')[1].split('【')[0];
assert(!facts.includes('戰車')&&!facts.includes('寶劍二')&&!facts.includes('正義'),'fictional example cards never enter the actual five-card facts');
for(const name of ['金幣皇后','聖杯皇后','金幣八','權杖王牌','金幣國王'])assert(facts.includes(name));
assert.equal(JSON.stringify(five),fiveBefore);
const copy=Q.narrativeExample('tarot');copy.text='MUTATED_EXAMPLE';assert(!Q.narrativeExample('tarot').text.includes('MUTATED_EXAMPLE'));
const stale={...Q,version:'5.0.0',readingVersion:'11.0.0',methodLines:()=>['STALE_SINGLE_CARD_REPORT'],recommendationEnding:()=> 'STALE_ENDING'};
c.JY_READING_QUALITY=stale;
const staleExport=P.build('tarot',five,q);assert(!staleExport.includes('STALE_SINGLE_CARD_REPORT')&&!staleExport.includes('STALE_ENDING'));
c.JY_READING_QUALITY=undefined;c.JYPromptPacket=undefined;load('liuren-prompt');
const bare=c.JYLiurenPrompt.build(fixture.l);
assert(bare.includes('【整體解說，不按資料順序朗讀】')&&bare.includes('"method":"liuren"')&&bare.includes('illustrative_only'));
c.JY_READING_QUALITY=Q;c.JYPromptPacket=P;
const broad=W.render({method:'ziwei',question:'完整分析十二宮與所有大限逐年流年'});
assert(broad.includes('【全盤作答覆蓋】')&&broad.includes('【逐年／逐期作答覆蓋】'));
const ootk=W.render({method:'ootk',question:q});assert(ootk.includes('第一至第五輪')&&ootk.includes('完整36張環牌故事'));
const api=fs.readFileSync(path.join(__dirname,'../functions/api/ai.js'),'utf8');
const block=api.match(/\/\/ BEGIN GENERATED READING SYSTEM_READING_STYLE\nvar SYSTEM_READING_STYLE = ([\s\S]*?);\n\/\/ END GENERATED READING SYSTEM_READING_STYLE/);
assert(block,'server style block exists');const serverStyle=JSON.parse(block[1]);
assert(serverStyle.includes(Q.narrativePolicy()),'API receives the same narrative and background boundary');
assert(api.includes('相反讀法須比較並收斂')&&api.includes('不宣稱真人身分、資歷或諮詢經驗'));
const report={release:'20261014universal25',status:'passed',methods:results,fiveCardSnapshot:{question:q,ids,positions,directions:Array.from(native.records,r=>r.direction),factsUnchanged:true,exampleCardsExcludedFromFacts:true},staleGuide:'passed',bareLiuren:'passed',fullAnnualAndOOTKCoverage:'passed',apiStyle:'passed',scope:'Actual local exporters and recorded card data; no live external-model response or prediction accuracy claim.'};
if(process.env.JY_PRACTITIONER_REPORT)fs.writeFileSync(process.env.JY_PRACTITIONER_REPORT,JSON.stringify(report,null,2)+'\n');
console.log('Practitioner narrative: 15 real exports, recorded five-card facts, isolated examples, fallback, API and coverage passed.');
